type SearchResultItemProps = {
  profession: Discipline
  searchString: string
  disabled: boolean
  onPress: () => Promise<void>
}

const SearchResultItem = ({ profession, searchString, disabled, onPress }: SearchResultItemProps): JSX.Element => (
  <Pressable key={profession.id} onPress={onPress} disabled={disabled}>
    {highlightText(splitTextBySearchString(profession.title, searchString), disabled)}
    <HorizontalLine />
  </Pressable>
)

{filteredProfessions?.map(profession => {
  const disabled = !!selectedProfessions?.includes(profession.id)
  return (
    <SearchResultItem
      key={profession.id}
      profession={profession}
      searchString={searchString}
      disabled={disabled}
      onPress={async () => {
        await pushSelectedProfession(profession.id).then(() => {
          navigation.navigate('ManageSelection')
        })
      }}
    />
  )
})}
